def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    # Locate each non-background isolated marker and place the horizontal ray tile
    # visible in demo 3: four 5s followed by a 9, extending rightward from marker.
    bg=max(set(v for row in grid for v in row), key=lambda v:sum(row.count(v) for row in grid))
    marker=next(v for v in set(x for row in grid for x in row) if v!=bg)
    for r in range(h):
        for c in range(w):
            if grid[r][c]==marker:
                for dc,val in enumerate((5,5,5,5,9)):
                    if c+dc<w: out[r][c+dc]=val
    return out
